def parse_csv(text):
    lines = [ln for ln in text.split("\n") if ln.strip()]
    if not lines:
        return []
    header = lines[0].split(",")
    rows = []
    for ln in lines[1:]:
        values = ln.split(",")
        row = {}
        for key, v in zip(header, values):
            row[key] = int(v) if v.lstrip("-").isdigit() else v
        rows.append(row)
    return rows

